
/*
 Small local SlickNav-style plugin for course projects.
 This creates a mobile menu from the desktop navigation.
*/
(function ($) {
    $.fn.slicknav = function (options) {
        var settings = $.extend({
            prependTo: "body",
            label: "Menu"
        }, options);

        return this.each(function () {
            var menu = $(this).find("ul").first().clone();
            var container = $('<div class="slicknav_menu"></div>');
            var button = $('<a href="#" class="slicknav_btn">' + settings.label + '</a>');
            var nav = $('<ul class="slicknav_nav"></ul>');

            menu.children("li").each(function () {
                nav.append($(this).clone());
            });

            nav.hide();
            button.on("click", function (event) {
                event.preventDefault();
                nav.slideToggle(200);
            });

            container.append(button);
            container.append(nav);
            $(settings.prependTo).append(container);
        });
    };
}(jQuery));
